from pathlib import Path

BASE = "9830bf3"

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(
            f"{label}: expected exactly 1 match, found {count}. "
            f"Make sure your working tree matches {BASE}."
        )
    return text.replace(old, new, 1)

# Replace server actions with feedback-returning versions.
actions_path = Path("app/(portal)/missions/actions.ts")
if not actions_path.exists():
    raise SystemExit("Missing app/(portal)/missions/actions.ts")
actions_path.write_text('"use server";\n\nimport { revalidatePath } from "next/cache";\nimport { createClient } from "@/lib/supabase/server";\n\nexport type DailyRewardClaimState = {\n  success: boolean;\n  message: string;\n};\n\nexport async function claimDailyMission(\n  _previousState: DailyRewardClaimState,\n  formData: FormData,\n): Promise<DailyRewardClaimState> {\n  const assignmentId = String(\n    formData.get("assignment_id") ?? "",\n  ).trim();\n\n  if (!assignmentId) {\n    return {\n      success: false,\n      message: "Daily Mission is required.",\n    };\n  }\n\n  const supabase = await createClient();\n  const { error } = await supabase.rpc(\n    "claim_my_daily_mission",\n    {\n      p_assignment_id: assignmentId,\n    },\n  );\n\n  if (error) {\n    return {\n      success: false,\n      message: error.message,\n    };\n  }\n\n  revalidatePath("/missions");\n  revalidatePath("/character");\n\n  return {\n    success: true,\n    message: "Reward received.",\n  };\n}\n\nexport async function claimDailyMilestone(\n  _previousState: DailyRewardClaimState,\n  formData: FormData,\n): Promise<DailyRewardClaimState> {\n  const claimId = String(\n    formData.get("claim_id") ?? "",\n  ).trim();\n\n  if (!claimId) {\n    return {\n      success: false,\n      message: "Daily Milestone is required.",\n    };\n  }\n\n  const supabase = await createClient();\n  const { error } = await supabase.rpc(\n    "claim_my_daily_mission_milestone",\n    {\n      p_claim_id: claimId,\n    },\n  );\n\n  if (error) {\n    return {\n      success: false,\n      message: error.message,\n    };\n  }\n\n  revalidatePath("/missions");\n  revalidatePath("/character");\n\n  return {\n    success: true,\n    message: "Reward received.",\n  };\n}\n', encoding="utf-8")
print("✓ app/(portal)/missions/actions.ts")

# Add reusable client claim UI.
component_path = Path("components/missions/daily-reward-claim.tsx")
if component_path.exists():
    raise SystemExit(
        "components/missions/daily-reward-claim.tsx already exists. "
        "Stop and inspect before re-running this patch."
    )
component_path.parent.mkdir(parents=True, exist_ok=True)
component_path.write_text('"use client";\n\nimport { useActionState } from "react";\n\nimport type {\n  DailyRewardClaimState,\n} from "@/app/(portal)/missions/actions";\n\nconst initialState: DailyRewardClaimState = {\n  success: false,\n  message: "",\n};\n\nfunction rewardText({\n  remnants,\n  itemName,\n  itemQuantity,\n}: {\n  remnants: number;\n  itemName: string | null;\n  itemQuantity: number;\n}) {\n  const parts: string[] = [];\n\n  if (remnants > 0) {\n    parts.push(`${remnants} Remnants`);\n  }\n\n  if (itemName && itemQuantity > 0) {\n    parts.push(`${itemQuantity} × ${itemName}`);\n  }\n\n  return parts.join(" · ");\n}\n\nexport function DailyRewardClaim({\n  action,\n  claimField,\n  claimId,\n  complete,\n  claimed,\n  remnants,\n  itemName,\n  itemQuantity,\n  compact = false,\n}: {\n  action: (\n    previousState: DailyRewardClaimState,\n    formData: FormData,\n  ) => Promise<DailyRewardClaimState>;\n  claimField: "assignment_id" | "claim_id";\n  claimId: string;\n  complete: boolean;\n  claimed: boolean;\n  remnants: number;\n  itemName: string | null;\n  itemQuantity: number;\n  compact?: boolean;\n}) {\n  const [state, formAction, pending] =\n    useActionState(\n      action,\n      initialState,\n    );\n\n  const reward = rewardText({\n    remnants,\n    itemName,\n    itemQuantity,\n  });\n\n  const dataProps =\n    claimField === "assignment_id"\n      ? { "data-mission-claim": true }\n      : { "data-milestone-claim": true };\n\n  return (\n    <form\n      action={formAction}\n      className={\n        compact ? "" : "mt-3"\n      }\n    >\n      <input\n        type="hidden"\n        name={claimField}\n        value={claimId}\n      />\n\n      <button\n        {...dataProps}\n        type="submit"\n        disabled={\n          !complete ||\n          claimed ||\n          pending\n        }\n        className={[\n          compact\n            ? "border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[9px] uppercase tracking-[0.14em]"\n            : "w-full border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[10px] uppercase tracking-[0.16em]",\n          "text-[rgb(var(--sep-colour-d9c092))] transition-colors enabled:hover:border-[rgb(var(--sep-colour-a07945))] enabled:hover:bg-[rgb(var(--sep-colour-302116))] disabled:cursor-not-allowed disabled:opacity-45",\n        ].join(" ")}\n      >\n        {pending\n          ? "Claiming..."\n          : claimed\n            ? "Claimed"\n            : complete\n              ? compact\n                ? "Claim"\n                : "Claim Reward"\n              : "In Progress"}\n      </button>\n\n      {state.message ? (\n        <p\n          role="status"\n          aria-live="polite"\n          className={[\n            compact\n              ? "mt-2 max-w-[290px] text-right"\n              : "mt-2 text-center",\n            "text-[9px] leading-4",\n            state.success\n              ? "text-[rgb(var(--sep-colour-d8bf91))]"\n              : "text-red-300",\n          ].join(" ")}\n        >\n          {state.success ? "✦ " : ""}\n          {state.success && reward\n            ? `Reward received — ${reward}.`\n            : state.message}\n        </p>\n      ) : null}\n    </form>\n  );\n}\n', encoding="utf-8")
print("✓ components/missions/daily-reward-claim.tsx")

# Replace the two plain server-action forms on the Missions page.
page_path = Path("app/(portal)/missions/page.tsx")
if not page_path.exists():
    raise SystemExit("Missing app/(portal)/missions/page.tsx")

text = page_path.read_text(encoding="utf-8")
text = replace_once(text, 'import {\n  MissionsLiveSync,\n} from "@/components/missions/missions-live-sync";\n', 'import {\n  MissionsLiveSync,\n} from "@/components/missions/missions-live-sync";\nimport {\n  DailyRewardClaim,\n} from "@/components/missions/daily-reward-claim";\n', "DailyRewardClaim import")
text = replace_once(text, '                <form action={claimDailyMilestone} className="mt-3">\n                  <input type="hidden" name="claim_id" value={milestone.id} />\n                  <button\n                    data-milestone-claim\n                    type="submit"\n                    disabled={!complete || milestone.claimed_at !== null}\n                    className="w-full border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[10px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-d9c092))] transition-colors enabled:hover:border-[rgb(var(--sep-colour-a07945))] enabled:hover:bg-[rgb(var(--sep-colour-302116))] disabled:cursor-not-allowed disabled:opacity-45"\n                  >\n                    {milestone.claimed_at\n                      ? "Claimed"\n                      : complete\n                        ? "Claim Reward"\n                        : "In Progress"}\n                  </button>\n                </form>', '                <DailyRewardClaim\n                  action={claimDailyMilestone}\n                  claimField="claim_id"\n                  claimId={milestone.id}\n                  complete={complete}\n                  claimed={milestone.claimed_at !== null}\n                  remnants={milestone.reward_remnants_snapshot}\n                  itemName={milestone.reward_item_name_snapshot}\n                  itemQuantity={milestone.reward_item_quantity_snapshot}\n                />', "Milestone claim form")
text = replace_once(text, '                        <form action={claimDailyMission}>\n                          <input\n                            type="hidden"\n                            name="assignment_id"\n                            value={mission.id}\n                          />\n                          <button\n                            data-mission-claim\n                            type="submit"\n                            disabled={!complete || mission.claimed_at !== null}\n                            className="border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-d9c092))] transition-colors enabled:hover:border-[rgb(var(--sep-colour-a07945))] enabled:hover:bg-[rgb(var(--sep-colour-302116))] disabled:cursor-not-allowed disabled:opacity-45"\n                          >\n                            {mission.claimed_at\n                              ? "Claimed"\n                              : complete\n                                ? "Claim"\n                                : "In Progress"}\n                          </button>\n                        </form>', '                        <DailyRewardClaim\n                          action={claimDailyMission}\n                          claimField="assignment_id"\n                          claimId={mission.id}\n                          complete={complete}\n                          claimed={mission.claimed_at !== null}\n                          remnants={mission.reward_remnants_snapshot}\n                          itemName={mission.reward_item_name_snapshot}\n                          itemQuantity={mission.reward_item_quantity_snapshot}\n                          compact\n                        />', "Mission claim form")
page_path.write_text(text, encoding="utf-8")
print("✓ app/(portal)/missions/page.tsx")

print()
print("Daily Mission claim feedback installed.")
print("Live-sync data hooks preserved.")
print("No SQL changes required.")
print("Run: npm run build")
